type ListResourceConnectionsParams struct {
	OrganizationID               string
	IdentityProviderConnectionID uuid.UUID
}

type ListResourceConnectionsRow struct {
	OktaResourceConnection OktaResourceConnection
	OktaApplicationLabel   pgtype.Text
}

// Resource connections of an identity provider connection with the label of the identity provider app
// instance the administrator picked, when the snapshot still has it.
func (q *Queries) ListResourceConnections(ctx context.Context, arg ListResourceConnectionsParams) ([]ListResourceConnectionsRow, error) {
	rows, err := q.db.Query(ctx, listResourceConnections, arg.OrganizationID, arg.IdentityProviderConnectionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListResourceConnectionsRow
	for rows.Next() {
		var i ListResourceConnectionsRow
		if err := rows.Scan(
			&i.OktaResourceConnection.ID,
			&i.OktaResourceConnection.OrganizationID,
			&i.OktaResourceConnection.IdentityProviderConnectionID,
			&i.OktaResourceConnection.RemoteSessionIssuerID,
			&i.OktaResourceConnection.Resource,
			&i.OktaResourceConnection.Audience,
			&i.OktaResourceConnection.OktaApplicationID,
			&i.OktaResourceConnection.CreatedAt,
			&i.OktaResourceConnection.UpdatedAt,
			&i.OktaApplicationLabel,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockLiveConnection = `-- name: LockLiveConnection :one
SELECT
    c.id
  , c.status
FROM identity_provider_connections AS c
WHERE c.id = $1
  AND c.organization_id = $2
  AND c.provider = 'okta'
  AND c.deleted IS FALSE
  AND c.status IN ('verified', 'degraded')
FOR UPDATE
`

type LockLiveConnectionParams struct {
	ID             uuid.UUID
	OrganizationID string
}

type LockLiveConnectionRow struct {
	ID     uuid.UUID
	Status string
}

// Held for the duration of a confirm or reset so a concurrent revoke, which
// takes the row FOR UPDATE, serializes against it. FOR UPDATE rather than
// FOR SHARE so waiters queue in order: a stream of share locks would starve
// the revoke indefinitely.
func (q *Queries) LockLiveConnection(ctx context.Context, arg LockLiveConnectionParams) (LockLiveConnectionRow, error) {
	row := q.db.QueryRow(ctx, lockLiveConnection, arg.ID, arg.OrganizationID)
	var i LockLiveConnectionRow
	err := row.Scan(&i.ID, &i.Status)
	return i, err
}

